const KEY="civil-edomex-v3";
let S={tab:"inicio",mod:0,ans:{},notes:{},read:{},fav:{},card:{},qs:{c:0,t:0},cs:{},mode:null,cd:"cc",bk:-1,ti:-1,q:"",sc:"all"};
try{const r3=localStorage.getItem(KEY),r2=localStorage.getItem("civil-edomex-v2");
 if(r3)S=Object.assign(S,JSON.parse(r3));
 else if(r2){const o=JSON.parse(r2),mg=ob=>{const n={};for(const k in ob||{})n[k.includes(":")?k:"cc:"+k]=ob[k];return n},nn={};
  for(const k in o.notes||{})nn[/^a\d/.test(k)?"a|cc:"+k.slice(1):k]=o.notes[k];
  o.read=mg(o.read);o.fav=mg(o.fav);o.card=mg(o.card);o.notes=nn;delete o.bk;delete o.ti;delete o.q;S=Object.assign(S,o)}}catch(e){}
let P={sel:null,show:60,quiz:null,fc:null,fcbk:-1,view:"menu"};
S=Object.assign({caseFiles:[],jurisprudencia:[],studyPlan:[],legalChecks:[]},S);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){toast("No fue posible guardar. Exporta tu respaldo.")}};
const esc=s=>s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const $=id=>document.getElementById(id);
const rk=(c,n)=>c+":"+n;
const score=(m,i)=>m.q.filter((q,k)=>(S.ans[i]||{})[k]===q.a).length;
const RX=/\{(cc|cp) ([^}]+)\}|\b(\d\.\d{1,4}(?:\.\d{1,2})?)((?: (?:[Bb]is|Ter|Quáter))?)\b/g;
function lk(t,c){return t.replace(RX,(m,tc,tn,a,b,off,s)=>{
 if(tc)return IDX[tc][tn]!==undefined?`<a onclick="openA('${tn}','${tc}')">${CODES[tc].s} ${tn}</a>`:m;
 if(!c)return m;const n=a+b;let t=c;const after=s.slice(off+m.length,off+m.length+50);
 if(c==="cp"&&/^\s*(de|del)( la)? (presente )?Código Civil/.test(after))t="cc";
 else if(c==="cc"&&/^\s*(de|del)( la)? (presente )?Código de Procedimientos/.test(after))t="cp";
 return IDX[t][n]!==undefined?`<a onclick="openA('${n}','${t}')">${m}</a>`:m})}
function bodyHTML(h,c){return h.replace(/(<[^>]+>)|([^<]+)/g,(x,tag,txt)=>tag?tag:lk(txt,c))}
function openA(n,c){S.tab="codigo";if(c&&S.cd!==c&&S.cd!=="all"){S.cd=c;S.bk=-1;S.ti=-1}P.sel={c:c||(S.cd==="all"?"cc":S.cd),n};save();render();window.scrollTo(0,0)}
function tabs(){const T=[["inicio","⌂ Inicio"],["curso","📖 Curso"],["codigo","📕 Códigos"],["ruta","🧭 Ruta procesal"],["casos","⚖️ Laboratorio"],["juris","📚 Jurisprudencia"],["practica","🎯 Practicar"],["prog","📊 Progreso"]];
 $("tabs").innerHTML=T.map(([k,l])=>`<button class="tab ${S.tab===k?'on':''}" onclick="S.tab='${k}';save();render()">${l}</button>`).join("")}
function render(){tabs();const fn=({inicio,curso,codigo,ruta,casos:caseLab,juris:jurisprudencia,practica,prog})[S.tab]||inicio;fn()}
function curso(){const i=S.mod,m=M[i],a=S.ans[i]||{};
 const grp=(c,t)=>`<div class="exp" style="margin:8px 0 4px"><b>${t}</b></div>`+M.map((x,k)=>x.c===c?`<button class="nb ${k===i?'on':''}" onclick="S.mod=${k};save();render()"><span>${x.ic} ${x.t}</span><small>${score(x,k)}/${x.q.length}</small></button>`:'').join("");
 $("app").innerHTML=`<div class="grid"><div class="side">${grp("cc","Derecho sustantivo · Código Civil")}${grp("cp","Derecho procesal · Código de Procedimientos")}</div><div class="main">
 <div class="card"><span class="pill" style="cursor:default">${CODES[m.c].s} · ${CODES[m.c].BN[m.b]}</span><h2>${m.ic} ${m.t}</h2>${bodyHTML(m.body,m.c)}<h3>Artículos clave (toca para leer el texto oficial)</h3>${m.refs.map(r=>`<button class="pill" onclick="openA('${r}','${m.c}')">Art. ${r}</button>`).join("")}</div>
 <div class="card"><h2>Ejercicios</h2><div class="bar"><i style="width:${Object.keys(a).length/m.q.length*100}%"></i></div>${m.q.map((q,qi)=>`<div style="margin-bottom:14px"><b>${qi+1}. ${esc(q.q)}</b>${q.o.map((o,oi)=>{let c="";if(a[qi]!==undefined){if(oi===q.a)c="ok";else if(oi===a[qi])c="no"}return`<button class="opt ${c}" ${a[qi]!==undefined?'disabled':''} onclick="pick(${i},${qi},${oi})">${esc(o)}</button>`}).join("")}${a[qi]!==undefined?`<p class="exp">${a[qi]===q.a?'✅ Correcto. ':'❌ Incorrecto. '}${esc(q.e)}</p>`:''}</div>`).join("")}${Object.keys(a).length===m.q.length?`<button class="btn g" onclick="delete S.ans[${i}];save();render()">Repetir</button>`:''}</div>
 <div class="card"><h3>Mis notas</h3><textarea oninput="S.notes['m${i}']=this.value;save()" placeholder="Tus apuntes…">${esc(S.notes['m'+i]||'')}</textarea></div>
 <div class="row">${i>0?`<button class="btn g" onclick="S.mod=${i-1};save();render()">← Anterior</button>`:''}${i<M.length-1?`<button class="btn" onclick="S.mod=${i+1};save();render()">Siguiente →</button>`:''}</div></div></div>`}
function pick(i,q,o){(S.ans[i]=S.ans[i]||{})[q]=o;save();render()}
function artHTML(c,n){const a=CODES[c].A[IDX[c][n]],k=rk(c,n),ix=IDX[c][n];
 return `<div class="card art"><span class="pill" style="cursor:default">${CODES[c].s} · ${CODES[c].BN[a.b]}</span><h2>Artículo ${a.n}</h2><p><b>${esc(a.h||'')}</b></p>${a.x.filter(Boolean).map(p=>`<p>${lk(esc(p),c)}</p>`).join("")}
 <div class="row"><button class="btn ${S.read[k]?'':'g'}" onclick="tg('read','${k}')">${S.read[k]?'✅ Leído':'Marcar como leído'}</button><button class="btn g" onclick="tg('fav','${k}')">${S.fav[k]?'★ Favorito':'☆ Favorito'}</button><button class="btn g" onclick="nav('${c}',${ix-1})">← Anterior</button><button class="btn g" onclick="nav('${c}',${ix+1})">Siguiente →</button></div>
 <h3>Mi nota</h3><textarea oninput="S.notes['a|${k}']=this.value;save()">${esc(S.notes['a|'+k]||'')}</textarea></div>`}
function tg(t,k){S[t][k]?delete S[t][k]:S[t][k]=1;save();render()}
function nav(c,i){const a=CODES[c].A[i];if(a){P.sel={c,n:a.n};render()}}
function getList(){const q=S.q.trim().toLowerCase(),cs=S.cd==="all"?["cc","cp"]:[S.cd],out=[];
 for(const c of cs)for(const a of CODES[c].A){let ok;
  if(q)ok=a.n.toLowerCase()===q||(/^\d/.test(q)&&a.n.toLowerCase().startsWith(q))||a.h.toLowerCase().includes(q)||a.x.join(" ").toLowerCase().includes(q);
  else if(S.cd==="all")ok=false;else ok=(S.bk<0||a.b===S.bk)&&(S.ti<0||a.t===S.ti);
  if(ok)out.push([c,a])}return out}
function setCd(v){S.cd=v;S.bk=-1;S.ti=-1;P.show=60;save();render()}
function codigo(){const one=S.cd!=="all",C=one?CODES[S.cd]:null,ti=one&&S.bk>=0?C.BK[S.bk].t:[];
 $("app").innerHTML=`<div class="grid"><div class="side"><div class="row" style="margin-bottom:8px">${[["cc","Civil"],["cp","Procesal"],["all","Ambos"]].map(([v,l])=>`<button class="tab ${S.cd===v?'on':''}" onclick="setCd('${v}')">${l}</button>`).join("")}</div>
 <input placeholder="Buscar: número, tema o palabra…" value="${esc(S.q)}" oninput="S.q=this.value;P.show=60;save();codigoList()" id="qi">
 ${one?`<select onchange="S.bk=+this.value;S.ti=-1;S.q='';P.show=60;save();render()"><option value="-1">Todos los libros</option>${C.BN.map((b,i)=>`<option value="${i}" ${S.bk===i?'selected':''}>${b}</option>`).join("")}</select>`:''}
 ${ti.length?`<select onchange="S.ti=+this.value;P.show=60;save();render()"><option value="-1">Todos los títulos</option>${ti.map((t,i)=>`<option value="${i}" ${S.ti===i?'selected':''}>${esc(t.length>70?t.slice(0,70)+'…':t)}</option>`).join("")}</select>`:''}
 <div class="exp" id="cnt"></div><div id="lst"></div></div><div class="main">${P.sel?artHTML(P.sel.c,P.sel.n):'<div class="card"><h2>Código Civil y Código de Procedimientos Civiles</h2><p>Elige un código y un libro, o busca por palabra («usucapión», «emplazamiento», «apelación») o por número (por ejemplo «4.91» o «2.107»). En «Ambos» la búsqueda recorre los dos códigos. Marca lo leído, guarda favoritos y escribe notas.</p><p class="exp">Tip: usa la pestaña <b>Ruta procesal</b> para ir del derecho al procedimiento.</p></div>'}</div></div>`;codigoList()}
function codigoList(){const list=getList();$("cnt").textContent=S.cd==="all"&&!S.q.trim()?"Escribe para buscar en ambos códigos":list.length+" artículos";
 $("lst").innerHTML=list.slice(0,P.show).map(([c,a])=>`<div class="ar ${S.read[rk(c,a.n)]?'rd':''}" onclick="P.sel={c:'${c}',n:'${a.n}'};render();window.scrollTo(0,0)"><b>${a.n}</b> <span class="pill" style="cursor:default;padding:0 7px;margin:0">${CODES[c].s}</span> ${S.fav[rk(c,a.n)]?'★ ':''}${esc(a.h||'(sin epígrafe)')}</div>`).join("")+(list.length>P.show?`<button class="btn g" onclick="P.show+=60;codigoList()">Mostrar más</button>`:'')}
function chips(arr){return arr.map(r=>{const[c,n]=r.includes(":")?r.split(":"):["",r];return `<button class="pill" onclick="openA('${n}','${c}')">${c?CODES[c].s+" ":""}${n}</button>`}).join("")}
function ruta(){const ch=(a,c)=>a.map(n=>`<button class="pill" onclick="openA('${n}','${c}')">${CODES[c].s} ${n}</button>`).join("");
 $("app").innerHTML=`<div class="card"><h2>🧭 De tu derecho al procedimiento</h2><p>Un abogado piensa en dos pasos: <b>¿qué derecho tengo?</b> (Código Civil) y <b>¿cómo lo hago valer?</b> (Código de Procedimientos). Toca cualquier artículo para leerlo.</p>${ROUTE.map(r=>`<div class="ar" style="cursor:default"><b>${r[0]}</b><br>${r[1].length?'Derecho: '+ch(r[1],'cc')+'<br>':''}Vía: <b>${r[2]}</b> ${ch(r[3],'cp')}</div>`).join("")}</div>
 <div class="card"><h2>Línea del juicio ordinario</h2><p class="exp">Orden general del trámite; algunos artículos del Código están derogados o cambian por reformas, verifica vigencia.</p>${STEPS.map((s,i)=>`<div class="ar" style="cursor:default"><b>${i+1}. ${s[0]}</b> <button class="pill" onclick="openA('${s[1]}','cp')">CPC ${s[1]}</button></div>`).join("")}</div>
 <div class="card"><h3>Aviso importante</h3><p class="exp">Este curso usa el texto del Código de Procedimientos Civiles del Estado de México con última reforma POGG 14-may-2021. En 2023 se publicó el Código Nacional de Procedimientos Civiles y Familiares, que entra en vigor por etapas, entidad por entidad, mediante declaratoria del Congreso local y con fechas que se han ido aplazando. Confirma qué código procesal se aplica hoy en tu caso y fecha antes de litigar o promover.</p></div>`}
const scope=()=>S.sc==="all"?["cc","cp"]:[S.sc];
const withH=()=>{const o=[];for(const c of scope())for(const a of CODES[c].A)if(a.h&&a.x.join(" ").length>60)o.push({c,a});return o};
const sh=a=>a.map(x=>[Math.random(),x]).sort((p,q)=>p[0]-q[0]).map(x=>x[1]);
function newQuiz(){const pool=withH(),qs=[];
 for(const it of sh(pool).slice(0,10)){const same=sh(pool.filter(b=>b.c===it.c&&b.a.b===it.a.b&&b.a.n!==it.a.n)).slice(0,3),opts=sh([it,...same]);
  qs.push({it,o:opts.map(x=>x.a.h),k:opts.indexOf(it),r:null})}
 P.quiz={qs,i:0};P.fc=null;P.view="quiz";render()}
function scSel(){return `<div class="row" style="margin-bottom:8px"><span class="exp">Material:</span>${[["all","Ambos"],["cc","Civil"],["cp","Procesal"]].map(([v,l])=>`<button class="tab ${S.sc===v?'on':''}" onclick="S.sc='${v}';save();${P.fc?'nextFC()':'render()'}">${l}</button>`).join("")}</div>`}
function practica(){const Q=P.quiz;
 let h=`<div class="card"><h2>Práctica</h2>${scSel()}<div class="row"><button class="btn" onclick="P.view='cases';P.fc=null;P.quiz=null;render()">🧩 Casos prácticos (10)</button><button class="btn g" onclick="newQuiz()">Quiz de epígrafes (10)</button><button class="btn g" onclick="startFC()">Tarjetas de repaso</button></div></div>`;
 if(P.view==="cases"&&!P.fc&&!Q)h+=CASES.map((c,i)=>{const a=S.cs[i];return `<div class="card"><span class="pill" style="cursor:default">Caso ${i+1}</span><p>${esc(c.h)}</p><b>${esc(c.q)}</b>${c.o.map((o,oi)=>`<button class="opt ${a!==undefined?(oi===c.a?'ok':oi===a?'no':''):''}" ${a!==undefined?'disabled':''} onclick="S.cs[${i}]=${oi};save();render()">${esc(o)}</button>`).join("")}${a!==undefined?`<p class="exp">${a===c.a?'✅ ':'❌ '}${esc(c.e)}</p>${chips(c.r)}`:''}</div>`}).join("");
 if(Q){if(Q.i>=Q.qs.length){const c=Q.qs.filter(q=>q.r===q.k).length;h+=`<div class="card"><h2>Resultado: ${c}/${Q.qs.length}</h2><button class="btn" onclick="newQuiz()">Otro quiz</button></div>`}
  else{const q=Q.qs[Q.i],{c,a}=q.it,tx=a.x.join(" ");h+=`<div class="card art"><span class="pill" style="cursor:default">Pregunta ${Q.i+1} de ${Q.qs.length} · ${CODES[c].s} · ${CODES[c].BN[a.b]}</span><p>«${esc(tx.slice(0,330))}${tx.length>330?'…':''}»</p><p><b>¿Qué epígrafe corresponde a este artículo?</b></p>${q.o.map((o,k)=>`<button class="opt ${q.r!==null?(k===q.k?'ok':k===q.r?'no':''):''}" ${q.r!==null?'disabled':''} onclick="ansQ(${k})">${esc(o)}</button>`).join("")}${q.r!==null?`<p class="exp">Es el artículo <a onclick="openA('${a.n}','${c}')">${CODES[c].s} ${a.n}</a>. <button class="btn" onclick="P.quiz.i++;render()">Siguiente →</button></p>`:''}</div>`}}
 if(P.fc)h+=fcHTML();$("app").innerHTML=h}
function ansQ(k){const q=P.quiz.qs[P.quiz.i];q.r=k;S.qs.t++;if(k===q.k)S.qs.c++;save();render()}
function startFC(){P.quiz=null;P.fc={flip:false,cur:null};nextFC()}
function nextFC(){const pool=withH().filter(x=>P.fcbk<0||x.a.b===P.fcbk||S.sc==="all"),due=pool.filter(x=>(S.card[rk(x.c,x.a.n)]||0)<3),src=due.length?due:pool;P.fc.cur=src[Math.floor(Math.random()*src.length)];P.fc.flip=false;render()}
function fcHTML(){const {c,a}=P.fc.cur,b=S.card[rk(c,a.n)]||0;
 return `<div class="card art fc"><span class="pill" style="cursor:default">Dominio ${b}/3 · ${CODES[c].s} · ${CODES[c].BN[a.b]}</span>${P.fc.flip?`<h3>Art. ${a.n} · ${esc(a.h)}</h3>${a.x.map(p=>`<p>${lk(esc(p),c)}</p>`).join("")}<div class="row" style="justify-content:center"><button class="btn" onclick="fcR(1)">Lo sé ✓</button><button class="btn g" onclick="fcR(0)">Repasar</button></div>`:`<h2>${esc(a.h)}</h2><p class="exp">Recuerda qué dice este artículo y su contenido.</p><button class="btn" onclick="P.fc.flip=true;render()">Ver artículo ${a.n}</button>`}</div>`}
function fcR(ok){const {c,a}=P.fc.cur,k=rk(c,a.n);S.card[k]=ok?Math.min(3,(S.card[k]||0)+1):0;save();nextFC()}
function prog(){const fav=Object.keys(S.fav),rd=Object.keys(S.read).length,tot=M.reduce((s,m)=>s+m.q.length,0),good=M.reduce((s,m,i)=>s+score(m,i),0),mast=Object.values(S.card).filter(v=>v>=3).length,cases=Object.keys(S.cs).filter(i=>S.cs[i]===CASES[i].a).length,TA=CODES.cc.A.length+CODES.cp.A.length;
 const per=["cc","cp"].map(c=>`<h3>${CODES[c].n}</h3>`+CODES[c].BN.map((b,i)=>{const t=CODES[c].A.filter(a=>a.b===i),r=t.filter(a=>S.read[rk(c,a.n)]).length;return`<p>${b}: <b>${r}/${t.length}</b> leídos<div class="bar"><i style="width:${r/t.length*100}%"></i></div></p>`}).join("")).join("");
 $("app").innerHTML=`<div class="card"><h2>Mi progreso</h2><p>Ejercicios del curso: <b>${good}/${tot}</b></p><div class="bar"><i style="width:${good/tot*100}%"></i></div><p>Casos prácticos acertados: <b>${cases}/${CASES.length}</b> · Artículos leídos: <b>${rd}/${TA}</b> · Tarjetas dominadas: <b>${mast}</b> · Quiz: <b>${S.qs.c}/${S.qs.t}</b> aciertos</p>${per}</div>
 <div class="card"><h3>Favoritos (${fav.length})</h3>${fav.length?fav.map(k=>{const[c,n]=k.split(":");return `<button class="pill" onclick="openA('${n}','${c}')">${CODES[c].s} ${n}</button>`}).join(""):'<p class="exp">Aún no tienes favoritos.</p>'}</div>
 <div class="card"><h3>Respaldo de progreso</h3><p class="exp">Tu avance vive en este navegador. Copia este texto para guardarlo o pégalo en otro dispositivo y pulsa Importar.</p><textarea id="bk" style="min-height:90px">${esc(JSON.stringify(S))}</textarea><div class="row"><button class="btn g" onclick="imp()">Importar</button><button class="btn g" onclick="toggleTheme()">Cambiar tema</button><button class="btn g" onclick="if(confirm('¿Borrar todo?')){S={tab:'prog',mod:0,ans:{},notes:{},read:{},fav:{},card:{},qs:{c:0,t:0},cs:{},mode:S.mode,cd:'cc',bk:-1,ti:-1,q:'',sc:'all'};save();render()}">Reiniciar todo</button></div></div>`}
function imp(){try{const raw=JSON.parse($("bk").value);if(!raw||typeof raw!=="object"||Array.isArray(raw))throw Error();const allowed=["tab","mod","ans","notes","read","fav","card","qs","cs","mode","cd","bk","ti","q","sc","caseFiles","jurisprudencia","studyPlan","legalChecks"];const clean={};for(const k of allowed)if(Object.prototype.hasOwnProperty.call(raw,k))clean[k]=raw[k];for(const k of ["ans","notes","read","fav","card","qs","cs"])if(clean[k]!==undefined&&(!clean[k]||typeof clean[k]!=="object"||Array.isArray(clean[k])))throw Error();if(clean.caseFiles!==undefined&&!Array.isArray(clean.caseFiles))throw Error();if(clean.jurisprudencia!==undefined&&!Array.isArray(clean.jurisprudencia))throw Error();S=Object.assign(S,clean);save();render();toast("Respaldo importado correctamente.")}catch(e){alert("Respaldo no válido o con estructura incompatible. No se modificaron tus datos.")}}

function toast(m){let n=document.getElementById('toast');if(!n){n=document.createElement('div');n.id='toast';n.className='toast';document.body.appendChild(n)}n.textContent=m;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2600)}
function inicio(){const read=Object.keys(S.read||{}).length, total=CODES.cc.A.length+CODES.cp.A.length, fav=Object.keys(S.fav||{}).length, good=M.reduce((s,m,i)=>s+score(m,i),0),q=M.reduce((s,m)=>s+m.q.length,0),cases=Object.keys(S.cs||{}).length;
 const recent=Object.entries(S.notes||{}).filter(([k,v])=>v&&k.startsWith('a|')).slice(-4);
 $("app").innerHTML=`<section class="hero card"><div><span class="eyebrow">PLATAFORMA DE ESTUDIO JURÍDICO</span><h2>IUS EDOMEX</h2><p>Estudia el derecho civil, comprende el procedimiento y aprende a construir argumentos jurídicos con método.</p><div class="row"><button class="btn" onclick="S.tab='curso';render()">Continuar estudiando</button><button class="btn g" onclick="S.tab='codigo';render()">Consultar legislación</button></div></div><div class="hero-mark">IUS<br><small>EDOMEX</small></div></section>
 <div class="stat-grid"><div class="stat card"><b>${read}</b><span>Artículos marcados</span><small>de ${total} en la biblioteca</small></div><div class="stat card"><b>${good}/${q}</b><span>Ejercicios del curso</span><small>respuestas correctas</small></div><div class="stat card"><b>${cases}</b><span>Casos contestados</span><small>práctica guiada</small></div><div class="stat card"><b>${fav}</b><span>Favoritos</span><small>artículos guardados</small></div></div>
 <div class="grid home-grid"><div class="card"><h3>Tu espacio de trabajo</h3><div class="launch" onclick="S.tab='codigo';render()"><span>📕</span><div><b>Biblioteca legislativa</b><small>Busca por artículo, concepto o texto.</small></div><strong>→</strong></div><div class="launch" onclick="S.tab='casos';render()"><span>⚖️</span><div><b>Laboratorio de casos</b><small>Ordena hechos, problemas, normas y pruebas.</small></div><strong>→</strong></div><div class="launch" onclick="S.tab='juris';render()"><span>📚</span><div><b>Fichero de jurisprudencia</b><small>Registra criterios y su aplicación al caso.</small></div><strong>→</strong></div><div class="launch" onclick="S.tab='ruta';render()"><span>🧭</span><div><b>Ruta procesal</b><small>Relaciona el derecho con la vía para hacerlo valer.</small></div><strong>→</strong></div></div>
 <div class="card"><h3>Método de análisis jurídico</h3><ol class="method"><li><b>Hechos:</b> separa lo probado de lo que solo afirma una parte.</li><li><b>Problema:</b> formula la pregunta jurídica concreta.</li><li><b>Norma:</b> identifica disposición, vigencia y ámbito de aplicación.</li><li><b>Prueba:</b> determina qué hecho acredita cada medio.</li><li><b>Argumento:</b> aplica la norma a los hechos y considera objeciones.</li><li><b>Conclusión:</b> explica el resultado y sus límites.</li></ol></div></div>
 <div class="card notice"><b>Control de vigencia</b><p>Los textos incluidos provienen del archivo fuente que compartiste. La fecha de reforma que aparece en ese archivo no sustituye la consulta de la Gaceta del Gobierno ni acredita por sí sola que el texto esté consolidado y vigente. Antes de usar una norma en una promoción, verifica publicación, reformas, transitorios, declaratoria de entrada en vigor y ámbito temporal.</p><p><a href="https://legislacion.edomex.gob.mx/" target="_blank" rel="noopener">Portal de Legislación del Estado de México ↗</a> · <a href="https://www.dof.gob.mx/" target="_blank" rel="noopener">Diario Oficial de la Federación ↗</a></p></div>`}
function caseLab(){const list=S.caseFiles||[];$("app").innerHTML=`<div class="page-head"><div><span class="eyebrow">ANÁLISIS Y ARGUMENTACIÓN</span><h2>Laboratorio de casos</h2><p>Construye una ficha de análisis sin confundir hechos, pretensiones, pruebas y conclusiones.</p></div><button class="btn" onclick="newCase()">＋ Nuevo análisis</button></div>
 <div class="grid lab-grid"><div class="card"><h3>Mis expedientes de estudio (${list.length})</h3>${list.length?list.map((c,i)=>`<div class="record"><b>${esc(c.title||'Caso sin título')}</b><small>${esc(c.topic||'Materia no indicada')} · ${esc(c.updated||'')}</small><div class="row"><button class="btn g" onclick="editCase(${i})">Abrir</button><button class="btn danger" onclick="deleteCase(${i})">Eliminar</button></div></div>`).join(''):'<p class="muted">Aún no has creado análisis. Inicia uno para practicar el método jurídico.</p>'}</div><div class="card"><h3>Plantilla de análisis</h3><p>Un buen análisis no empieza buscando un artículo al azar. Primero delimita qué ocurrió, qué se pide y qué debe demostrarse.</p><ol><li>Identifica a las partes y sus posiciones.</li><li>Ordena hechos por fecha.</li><li>Formula una o más preguntas jurídicas.</li><li>Busca normas y criterios aplicables.</li><li>Asocia pruebas con hechos concretos.</li><li>Plantea la mejor objeción y responde.</li></ol></div></div>`}
function newCase(){caseEditor({title:'',topic:'Civil',facts:'',issue:'',claim:'',law:'',evidence:'',counter:'',conclusion:'',source:'',date:new Date().toLocaleDateString('es-MX')},-1)}
function editCase(i){caseEditor(S.caseFiles[i],i)}
function caseEditor(c,i){$("app").innerHTML=`<div class="page-head"><div><span class="eyebrow">FICHA DE TRABAJO</span><h2>${i<0?'Nuevo análisis':'Editar análisis'}</h2></div><button class="btn g" onclick="caseLab()">← Volver</button></div><div class="card editor"><label>Título del caso</label><input id="ctitle" value="${esc(c.title)}" placeholder="Ej. Incumplimiento de contrato de compraventa"><label>Materia</label><select id="ctopic">${['Civil','Familiar','Sucesorio','Obligaciones y contratos','Bienes','Procesal civil','Otra'].map(x=>`<option ${c.topic===x?'selected':''}>${x}</option>`).join('')}</select><label>Hechos relevantes (cronología y datos comprobables)</label><textarea id="cfacts">${esc(c.facts)}</textarea><label>Problema jurídico (pregunta concreta)</label><textarea id="cissue">${esc(c.issue)}</textarea><label>Pretensión o defensa de cada parte</label><textarea id="cclaim">${esc(c.claim)}</textarea><label>Normas aplicables y control de vigencia</label><textarea id="claw">${esc(c.law)}</textarea><label>Pruebas: qué hecho acredita cada una y posibles objeciones</label><textarea id="cevidence">${esc(c.evidence)}</textarea><label>Contraargumento / excepción / defensa</label><textarea id="ccounter">${esc(c.counter)}</textarea><label>Conclusión provisional y riesgos</label><textarea id="cconclusion">${esc(c.conclusion)}</textarea><label>Fuente oficial / datos de identificación</label><textarea id="csource">${esc(c.source)}</textarea><div class="row"><button class="btn" onclick="saveCase(${i})">Guardar análisis</button><button class="btn g" onclick="caseLab()">Cancelar</button></div></div>`}
function saveCase(i){const val=id=>document.getElementById(id).value.trim(),c={title:val('ctitle'),topic:val('ctopic'),facts:val('cfacts'),issue:val('cissue'),claim:val('cclaim'),law:val('claw'),evidence:val('cevidence'),counter:val('ccounter'),conclusion:val('cconclusion'),source:val('csource'),updated:new Date().toLocaleDateString('es-MX')};if(!c.title){toast('Escribe un título para identificar el caso.');return}if(i<0)S.caseFiles.unshift(c);else S.caseFiles[i]=c;save();caseLab();toast('Análisis guardado.')}
function deleteCase(i){if(confirm('¿Eliminar este análisis?')){S.caseFiles.splice(i,1);save();caseLab()}}
function jurisprudencia(){const list=S.jurisprudencia||[];$("app").innerHTML=`<div class="page-head"><div><span class="eyebrow">INVESTIGACIÓN DE CRITERIOS</span><h2>Fichero de jurisprudencia</h2><p>Registra tesis y precedentes con datos suficientes para localizarlos y evaluar su aplicación.</p></div><button class="btn" onclick="newJuris()">＋ Agregar criterio</button></div><div class="notice card"><b>Importante:</b> una ficha capturada por el usuario no equivale a una verificación oficial. Comprueba registro digital, órgano, época, tipo de criterio, texto íntegro, vigencia y posibles criterios posteriores.</div><div class="grid lab-grid"><div class="card"><h3>Criterios guardados (${list.length})</h3>${list.length?list.map((j,i)=>`<div class="record"><b>${esc(j.rubro||'Sin rubro')}</b><small>${esc(j.type||'Tipo no indicado')} · ${esc(j.court||'Órgano no indicado')}</small><small>Registro: ${esc(j.registry||'No capturado')}</small><div class="row"><button class="btn g" onclick="editJuris(${i})">Ver / editar</button><button class="btn danger" onclick="deleteJuris(${i})">Eliminar</button></div></div>`).join(''):'<p class="muted">No hay criterios registrados.</p>'}</div><div class="card"><h3>Campos que debes verificar</h3><ul><li>Rubro exacto.</li><li>Registro digital o identificador oficial.</li><li>Órgano jurisdiccional y época.</li><li>Tipo: jurisprudencia, precedente o tesis aislada.</li><li>Hechos y problema jurídico.</li><li>Ratio decidendi / criterio sostenido.</li><li>Normas interpretadas y aplicación al caso.</li><li>Enlace a fuente oficial y fecha de consulta.</li></ul><a href="https://sjf2.scjn.gob.mx/" target="_blank" rel="noopener">Consultar Semanario Judicial de la Federación ↗</a></div></div>`}
function newJuris(){jurisEditor({rubro:'',registry:'',court:'',epoch:'',type:'',facts:'',issue:'',criterion:'',application:'',source:'',checked:''},-1)}function editJuris(i){jurisEditor(S.jurisprudencia[i],i)}
function jurisEditor(j,i){$("app").innerHTML=`<div class="page-head"><h2>${i<0?'Nuevo criterio':'Editar criterio'}</h2><button class="btn g" onclick="jurisprudencia()">← Volver</button></div><div class="card editor"><label>Rubro</label><textarea id="jrubro">${esc(j.rubro)}</textarea><label>Registro digital / identificador</label><input id="jregistry" value="${esc(j.registry)}"><label>Órgano jurisdiccional</label><input id="jcourt" value="${esc(j.court)}"><label>Época / fecha</label><input id="jepoch" value="${esc(j.epoch)}"><label>Tipo de criterio</label><select id="jtype">${['Jurisprudencia','Precedente obligatorio','Tesis aislada','Otro / por verificar'].map(x=>`<option ${j.type===x?'selected':''}>${x}</option>`).join('')}</select><label>Hechos relevantes</label><textarea id="jfacts">${esc(j.facts)}</textarea><label>Problema jurídico</label><textarea id="jissue">${esc(j.issue)}</textarea><label>Criterio / razón decisoria</label><textarea id="jcriterion">${esc(j.criterion)}</textarea><label>Cómo se relaciona con mi caso</label><textarea id="japplication">${esc(j.application)}</textarea><label>Fuente oficial (URL)</label><input id="jsource" value="${esc(j.source)}"><label>Fecha de verificación</label><input id="jchecked" type="date" value="${esc(j.checked)}"><div class="row"><button class="btn" onclick="saveJuris(${i})">Guardar criterio</button><button class="btn g" onclick="jurisprudencia()">Cancelar</button></div></div>`}
function saveJuris(i){const v=id=>document.getElementById(id).value.trim(),j={rubro:v('jrubro'),registry:v('jregistry'),court:v('jcourt'),epoch:v('jepoch'),type:v('jtype'),facts:v('jfacts'),issue:v('jissue'),criterion:v('jcriterion'),application:v('japplication'),source:v('jsource'),checked:v('jchecked')};if(!j.rubro){toast('Captura el rubro del criterio.');return}if(i<0)S.jurisprudencia.unshift(j);else S.jurisprudencia[i]=j;save();jurisprudencia();toast('Criterio guardado.')}
function deleteJuris(i){if(confirm('¿Eliminar este criterio?')){S.jurisprudencia.splice(i,1);save();jurisprudencia()}}
function toggleTheme(){const d=document.documentElement,dk=getComputedStyle(d).getPropertyValue("--bg").trim()==="#15171c";d.dataset.theme=dk?"light":"dark";S.mode=d.dataset.theme;save()}
if(S.mode)document.documentElement.dataset.theme=S.mode;
render();

function exportBackup(){const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ius-edomex-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url);toast('Respaldo descargado.')}
